import { withRequest } from 'yapyak/adapter';

function handler(request: Request): Response {
  return withRequest(request, () => renderApp(request));
}

import { sequence } from 'astro:middleware';
import { middleware as yapyakMiddleware } from 'yapyak/adapter/astro';
import { middleware as authMiddleware } from './auth';

export const onRequest = sequence(yapyakMiddleware, authMiddleware);

import type { Route } from './+types/root';
import { middleware as yapyakMiddleware } from 'yapyak/adapter/react-router';

export const middleware: Route.MiddlewareFunction[] = [yapyakMiddleware];

