t('Save changes');

t('Hello, {name}!', { name: 'Alex' });

t('You have {count, plural, one {# item} other {# items}}', { count: 1 });

t.in(user.locale)('Welcome back, {name}!', { name: user.name });

import { IntlProvider } from 'yapyak/react';

function App() {
  return (
    <IntlProvider>
      <App />
    </IntlProvider>
  );
}

import { t } from 'yapyak';
import { useLocale } from 'yapyak/react';

function LocaleToggle() {
  const [locale, setLocale] = useLocale();
  return (
    <select value={locale} onChange={(e) => setLocale(e.target.value)}>
      <option value="en">English</option>
      <option value="sv">Svenska</option>
    </select>
  );
}

import { anthropic } from 'yapyak/translator';

yapyak({
  translator: anthropic({ apiKey: process.env.ANTHROPIC_API_KEY! }),
});

const myTranslator = createTranslator({
  async translate({ items, sourceLocale, targetLocale }) {
    const response = await fetch('https://my-api.example/translate', {
      method: 'POST',
      body: JSON.stringify({ items, sourceLocale, targetLocale }),
    });
    const { translations } = await response.json();
    return translations;
  },
});

import { gemini } from 'yapyak/translator';

yapyak({
  translator: gemini({ apiKey: process.env.GOOGLE_API_KEY! }),
});

import { ollama } from 'yapyak/translator';

yapyak({
  translator: ollama({ model: 'llama3.1' }),
});

import { openai } from 'yapyak/translator';

yapyak({
  translator: openai({ apiKey: process.env.OPENAI_API_KEY! }),
});

async function myTranslate(params: TranslateBatchRequest): Promise<string[]> {
  const response = await fetch('https://api.example/translate', {
    method: 'POST',
    body: JSON.stringify(params),
    signal: params.signal,
  });
  const { translations } = await response.json();
  return translations;
}

createTranslator({ translate: myTranslate });

function buildTranslator(level: ContextLevel) {
  return createTranslator({ context: level, translate: ... });
}

import { defineConfig } from 'vite';
import { yapyak } from 'yapyak/vite';
